  "book_code":"2ES",
  "verses":[
    {
      "chapter":16,
      "verse":61,
      "text_ar":"خَلَقَ الإِنسان، وجَعَلَ في طَلَب القَلب، وأَوحى إليه نفَسًا، والحَياة، والفَهْم.",
      "review_notes_ar":[]
    },
    {
      "chapter":16,
      "verse":62,
      "text_ar":"نَعَم، روحَ الله القَدِير. الخالِقُ لكل شَيء، وغَاصِبُ ما استُخفِيَ على الخِفا",
      "review_notes_ar":[]
    },
    {
      "chapter":16,
      "verse":63,
      "text_ar":"إِنَّه عارِفُ بِما بِهِ تُخلَقُ الخَلائِق، وما بجَهاتِك في خِبا. عَيا لِمَن كَذَبوا، ودارَوا لِيُخفوا خِبا",
      "review_notes_ar":[]
    },
    {
      "chapter":16,
      "verse":64,
      "text_ar":"فَإِنَّ الرَّبَّ يَحكُمُ قَضاءً كُلَّ عملِكُم، وإِنَّه يُخزِيكم بإِبلاغِ خِبا",
      "review_notes_ar":[]
    },
    {
      "chapter":16,
      "verse":65,
      "text_ar":"حَتَّى إِذا أُظهِرت ذُنوبٌ بَينَ القوم سَئِم، وحَسبتُم أَنَّها في الدّاه تَخفي، فالحَقيقَتُ يُذاعت كَأَشياع، وعارٌ ما طابَه حِيناً ما حاشا",
      "review_notes_ar":[]
    }
  ]
}
